class LiveExerciseCheckPage extends StatefulWidget { final String exerciseId; const LiveExerciseCheckPage({super.key,required this.exerciseId}); @override State<LiveExerciseCheckPage> createState()=>_LiveExerciseCheckPageState(); }
class _LiveExerciseCheckPageState extends State<LiveExerciseCheckPage> with WidgetsBindingObserver {
 CameraController? camera; NpuPoseDetector? detector; ExerciseAnalyzer? analyzer; Future<void>? ready; bool running=false,busy=false,front=true; String status='READY'; ExerciseFeedback? feedback; dynamic pose; int reps=0; final List<int> repScores=[];
 ExerciseCatalogItem get exercise=>exerciseById(widget.exerciseId);
 @override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);analyzer=ExerciseRegistry.create(widget.exerciseId);_initCamera();}
 Future<void> _initCamera() async {try{await camera?.dispose();final cams=await availableCameras();if(cams.isEmpty)throw Exception('No camera found');final selected=cams.firstWhere((c)=>c.lensDirection==(front?CameraLensDirection.front:CameraLensDirection.back),orElse:()=>cams.first);final c=CameraController(selected,ResolutionPreset.medium,enableAudio:false,imageFormatGroup:ImageFormatGroup.yuv420);final f=c.initialize();if(mounted)setState((){camera=c;ready=f;status='READY';});await f;}catch(_){if(mounted)setState(()=>status='CAMERA ERROR');}}
